const items = $input.all();
let client = null;
let config = {};
let invoiceRow = null;

for (const item of items) {
  const json = item?.json;
  if (!json) continue;
  if (json.integration_type === 'notaas' || (json.config && json.config.api_key !== undefined)) {
    config = json.config ?? {};
  } else if (json.type === 'nfse' || json.valor_servico !== undefined) {
    invoiceRow = json;
  } else if (json.document !== undefined || json.address_city !== undefined) {
    client = json;
  }
}

if (!client) client = items[0]?.json;
if (!config.api_key && items[2]?.json?.config) config = items[2].json.config;

const invoiceId    = invoiceRow?.id            || null;
const paymentId    = invoiceRow?.payment_id    || null;
const valor        = invoiceRow?.valor_servico || 0;
const competencia  = invoiceRow?.competencia   || null;
const dueDate      = invoiceRow?.due_date      || null;
const notaasId     = invoiceRow?.notaas_id !== undefined ? invoiceRow.notaas_id : null;
const codigoSaved  = invoiceRow?.codigo_servico    ? invoiceRow.codigo_servico.replace(/\D/g, '') : null;
const descSaved    = invoiceRow?.descricao_servico || null;
const aliqSaved    = invoiceRow?.aliquota_iss      ?? null;
const serviceType  = null;
const action       = 'emit';

if (!client?.id) throw new Error('Cliente não encontrado');
if (!config.api_key) throw new Error('API Key da Notaas não configurada');

// CPF (11 dígitos) ou CNPJ (14 dígitos) — campos separados, nunca os dois juntos
const docDigits = (client.document || '').replace(/\D/g, '');
const isCpf  = docDigits.length === 11;
const isCnpj = docDigits.length === 14;

let codigoServico, descricaoServico, aliquotaIss;
if (codigoSaved) {
  codigoServico    = codigoSaved;
  descricaoServico = descSaved || config.descricao_servico_padrao || 'Prestação de serviços';
  aliquotaIss      = aliqSaved != null ? aliqSaved : (config.aliquota_iss_padrao ?? 5);
} else {
  const mappings = config.codigos_servico_por_tipo_contrato ?? {};
  const mapping  = serviceType ? mappings[serviceType] : null;
  if (mapping && typeof mapping === 'object') {
    codigoServico    = (mapping.codigo    || config.codigo_servico_padrao    || '').replace(/\D/g, '');
    descricaoServico = mapping.descricao || config.descricao_servico_padrao || 'Prestação de serviços';
    aliquotaIss      = mapping.aliquota  != null ? mapping.aliquota : (config.aliquota_iss_padrao ?? 5);
  } else if (mapping && typeof mapping === 'string') {
    codigoServico    = mapping.replace(/\D/g, '');
    descricaoServico = config.descricao_servico_padrao || 'Prestação de serviços';
    aliquotaIss      = config.aliquota_iss_padrao ?? 5;
  } else {
    codigoServico    = (config.codigo_servico_padrao || '').replace(/\D/g, '');
    descricaoServico = config.descricao_servico_padrao || 'Prestação de serviços';
    aliquotaIss      = config.aliquota_iss_padrao ?? 5;
  }
}

if (!codigoServico) throw new Error('Código de serviço não configurado');

const endereco = {
  logradouro:  client.address_street       || '',
  numero:      client.address_number       || '',
  complemento: client.address_complement   || '',
  bairro:      client.address_neighborhood || '',
  cidade:      client.address_city         || '',
  uf:          client.address_state        || '',
  cep:         client.address_zip          || ''
};

// Monta tomador com cpf OU cnpj primeiro (ordem importa para o schema XML da NFS-e)
const tomador = {};
if (isCpf)       tomador.cpf  = docDigits;
else if (isCnpj) tomador.cnpj = docDigits;
tomador.nome     = client.company || client.name;
tomador.email    = client.email   || null;
tomador.endereco = endereco;

const baseUrl = config.sandbox_mode === true
  ? 'https://sandbox.notaas.com.br'
  : 'https://platform.notaas.com.br';

return [{ json: {
  invoice_id:        invoiceId,
  payment_id:        paymentId,
  notaas_id:         notaasId,
  action,
  valor_servico:     valor,
  aliquota_iss:      aliquotaIss,
  codigo_servico:    codigoServico,
  descricao_servico: descricaoServico,
  competencia,
  due_date:          dueDate,
  notaas_payload: {
    tomador,
    servico:    { codigo: codigoServico, descricao: descricaoServico },
    valores:    { total: valor, aliquotaIss },
    competencia
  },
  api_key:  config.api_key,
  base_url: baseUrl
}}];

