// Normaliza o payload e detecta o tipo de ação
const body = $input.item.json.body || $input.item.json;
const invoiceId    = body.invoice_id    || null;
const notaas_id    = body.notaas_id   || null;
const pdf_url    = body.pdf_url   || null;
const emitida_em    = body.emitida_em   || null;
const erro_mensagem    = body.erro_mensagem   || null;
const paymentId    = body.payment_id    || null;
const clientId     = body.client_id     || null;
const orgId        = body.organization_id;
const valor        = parseFloat(body.valor) || 0;
const paidAt       = body.paid_at || new Date().toISOString();
const serviceType  = body.service_contracted || null;
const contractId   = body.contract_id || null;
const action       = body._action || 'emit';

if (!orgId) throw new Error('organization_id é obrigatório');
if (!invoiceId) throw new Error('invoice_id é obrigatório — o Maestr.IA deve criar o invoice antes de acionar este webhook');

// Deriva competência (YYYY-MM) a partir de paid_at
const d = new Date(paidAt);
const competencia = `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}`;

return [{ json: {
  invoice_id:     invoiceId,
  payment_id:     paymentId,
  client_id:      clientId,
  organization_id: orgId,
  valor,
  paid_at:        paidAt,
  service_type:   serviceType,
  contract_id:    contractId,
  competencia,
  action,
    notaas_id,       // ← adicionado
  pdf_url,         // ← adicionado
  emitida_em,      // ← adicionado
  erro_mensagem    // ← adicionado
}}];

// Valida que o invoice existe e está em estado emissível
const arr = $input.item.json;
const invoice = Array.isArray(arr) ? arr[0] : arr;

if (!invoice?.id) {
  throw new Error(`Invoice não encontrado: ${$('Parsear Payload').item.json.invoice_id}`);
}

const parsed = $('Parsear Payload').item.json;
const action = parsed.action || 'emit';

// check_or_emit: aceita qualquer status exceto autorizada/cancelada
// emit/sync: aceita processando, pendente, rejeitada
const emissiveStatuses = action === 'check_or_emit'
  ? ['processando', 'pendente', 'rejeitada']
  : ['processando', 'pendente', 'rejeitada'];

if (!emissiveStatuses.includes(invoice.status)) {
  throw new Error(`Invoice ${invoice.id} está com status '${invoice.status}' — não pode ser (re)emitido`);
}

const clientId   = invoice.client_id   || parsed.client_id;
const orgId      = invoice.organization_id || parsed.organization_id;
const serviceType = parsed.service_type;

return [{ json: {
  invoice_id:      invoice.id,
  invoice_status:  invoice.status,
  notaas_id:       invoice.notaas_id || null,
  client_id:       clientId,
  organization_id: orgId,
  valor:           invoice.valor_servico || parsed.valor,
  competencia:     invoice.competencia  || parsed.competencia,
  service_type:    serviceType,
  contract_id:     invoice.contract_id  || parsed.contract_id,
  action,
  codigo_servico_saved:    invoice.codigo_servico,
  descricao_servico_saved: invoice.descricao_servico,
  aliquota_iss_saved:      invoice.aliquota_iss
}}];

const input = $input.item.json;
const supabaseUrl = input._supabase_url;
const serviceKey = input._service_key;

if (!supabaseUrl || !serviceKey) {
  throw new Error('Variaveis SUPABASE_URL e SUPABASE_SERVICE_KEY nao configuradas');
}

const sbH = {
  'apikey': serviceKey,
  'Authorization': 'Bearer ' + serviceKey,
  'Content-Type': 'application/json'
};

// Busca notas em processando há mais de 10 minutos
const cutoff = new Date(Date.now() - 10 * 60 * 1000).toISOString();
const invRes = await fetch(
  supabaseUrl + '/rest/v1/invoices?status=eq.processando&updated_at=lt.' + cutoff + '&select=id,organization_id,client_id,contract_id,payment_id,valor_servico,aliquota_iss,codigo_servico,descricao_servico,competencia,notaas_id,notaas_protocol,numero,pdf_url,xml_url,emitida_em,erro_mensagem&limit=50',
  { headers: sbH }
);
if (!invRes.ok) throw new Error('Erro ao buscar invoices: ' + invRes.status);
const invoices = await invRes.json();

if (!Array.isArray(invoices) || invoices.length === 0) {
  return [{ json: { checked: 0, message: 'Nenhuma nota em processamento para verificar' } }];
}

const results = [];

for (const invoice of invoices) {
  const orgId = invoice.organization_id;

  // Busca config Notaas da organização
  const configRes = await fetch(
    supabaseUrl + '/rest/v1/organization_integrations?organization_id=eq.' + orgId + '&integration_type=eq.notaas&select=config',
    { headers: sbH }
  );
  if (!configRes.ok) {
    results.push({ id: invoice.id, result: 'skip', reason: 'config_error' });
    continue;
  }
  const configArr = await configRes.json();
  const config = Array.isArray(configArr) ? (configArr[0] && configArr[0].config ? configArr[0].config : {}) : {};

  if (!config.api_key) {
    results.push({ id: invoice.id, result: 'skip', reason: 'no_api_key' });
    continue;
  }

  const baseUrl = config.sandbox_mode === true
    ? 'https://sandbox.notaas.com.br'
    : 'https://platform.notaas.com.br';

  // Se tem notaas_id, consulta o status na Notaas
  if (invoice.notaas_id) {
    try {
      const checkRes = await fetch(baseUrl + '/api/v1/notas/' + invoice.notaas_id, {
        headers: { 'x-api-key': config.api_key, 'Content-Type': 'application/json' },
        signal: AbortSignal.timeout(15000)
      });

      if (checkRes.ok) {
        const nota = await checkRes.json();
        if (nota && (nota.id || nota.numero)) {
          // Nota autorizada na Notaas
          await fetch(supabaseUrl + '/rest/v1/invoices?id=eq.' + invoice.id, {
            method: 'PATCH',
            headers: Object.assign({}, sbH, { 'Prefer': 'return=minimal' }),
            body: JSON.stringify({
              status: 'autorizada',
              notaas_id: nota.id || invoice.notaas_id,
              notaas_protocol: nota.protocol || null,
              numero: nota.numero || null,
              pdf_url: nota.pdf_url || null,
              xml_url: nota.xml_url || null,
              emitida_em: nota.emitida_em || new Date().toISOString(),
              erro_mensagem: null
            })
          });
          results.push({ id: invoice.id, result: 'autorizada', numero: nota.numero });
          continue;
        }
      } else if (checkRes.status === 404) {
        // Nota não encontrada na Notaas — marca como rejeitada
        await fetch(supabaseUrl + '/rest/v1/invoices?id=eq.' + invoice.id, {
          method: 'PATCH',
          headers: Object.assign({}, sbH, { 'Prefer': 'return=minimal' }),
          body: JSON.stringify({
            status: 'rejeitada',
            erro_mensagem: 'Nota não encontrada na Notaas após verificação automática'
          })
        });
        results.push({ id: invoice.id, result: 'rejeitada', reason: 'not_found_in_notaas' });
        continue;
      } else {
        const errBody = await checkRes.json().catch(function() { return {}; });
        const errMsg = errBody.message || errBody.error || ('Erro HTTP ' + checkRes.status);
        await fetch(supabaseUrl + '/rest/v1/invoices?id=eq.' + invoice.id, {
          method: 'PATCH',
          headers: Object.assign({}, sbH, { 'Prefer': 'return=minimal' }),
          body: JSON.stringify({ status: 'rejeitada', erro_mensagem: errMsg })
        });
        results.push({ id: invoice.id, result: 'rejeitada', reason: errMsg });
        continue;
      }
    } catch (e) {
      // Timeout ou erro de rede — deixa em processando para próxima verificação
      results.push({ id: invoice.id, result: 'skip', reason: 'network_error: ' + e.message });
      continue;
    }
  }

  // Sem notaas_id — nota nunca chegou à Notaas, tenta emitir agora
  // Busca dados do cliente
  const clientRes = await fetch(
    supabaseUrl + '/rest/v1/clients?id=eq.' + invoice.client_id + '&select=id,name,company,document,email,address_street,address_number,address_complement,address_neighborhood,address_city,address_state,address_zip',
    { headers: sbH }
  );
  if (!clientRes.ok) {
    results.push({ id: invoice.id, result: 'skip', reason: 'client_fetch_error' });
    continue;
  }
  const clientArr = await clientRes.json();
  const client = Array.isArray(clientArr) ? clientArr[0] : clientArr;
  if (!client || !client.id) {
    results.push({ id: invoice.id, result: 'skip', reason: 'client_not_found' });
    continue;
  }

  const codigoServico = invoice.codigo_servico || config.codigo_servico_padrao || '';
  const descricaoServico = invoice.descricao_servico || config.descricao_servico_padrao || 'Prestacao de servicos';
  const aliquotaIss = invoice.aliquota_iss != null ? invoice.aliquota_iss : (config.aliquota_iss_padrao || 5);

  if (!codigoServico) {
    await fetch(supabaseUrl + '/rest/v1/invoices?id=eq.' + invoice.id, {
      method: 'PATCH',
      headers: Object.assign({}, sbH, { 'Prefer': 'return=minimal' }),
      body: JSON.stringify({ status: 'rejeitada', erro_mensagem: 'Codigo de servico nao configurado' })
    });
    results.push({ id: invoice.id, result: 'rejeitada', reason: 'no_codigo_servico' });
    continue;
  }

  const notaasPayload = {
    tomador: {
      cnpj: client.document,
      nome: client.company || client.name,
      email: client.email || null,
      endereco: {
        logradouro: client.address_street || '',
        numero: client.address_number || '',
        complemento: client.address_complement || '',
        bairro: client.address_neighborhood || '',
        cidade: client.address_city || '',
        uf: client.address_state || '',
        cep: client.address_zip || ''
      }
    },
    servico: { codigo: codigoServico, descricao: descricaoServico },
    valores: { total: invoice.valor_servico, aliquotaIss },
    competencia: invoice.competencia
  };

  try {
    const emitRes = await fetch(baseUrl + '/api/v1/emitir', {
      method: 'POST',
      headers: { 'x-api-key': config.api_key, 'Content-Type': 'application/json', 'User-Agent': 'MaestrIA-n8n-check/1.0' },
      body: JSON.stringify(notaasPayload),
      signal: AbortSignal.timeout(30000)
    });
    const emitBody = await emitRes.json().catch(function() { return {}; });
    const externalId = emitBody.id || emitBody.notaas_id || emitBody.nota_id || emitBody.uuid || null;
    const numero = emitBody.numero || emitBody.number || null;

    if (emitRes.ok && (externalId || numero)) {
      await fetch(supabaseUrl + '/rest/v1/invoices?id=eq.' + invoice.id, {
        method: 'PATCH',
        headers: Object.assign({}, sbH, { 'Prefer': 'return=minimal' }),
        body: JSON.stringify({
          status: 'autorizada',
          notaas_id: externalId,
          notaas_protocol: emitBody.protocol || null,
          numero,
          pdf_url: emitBody.pdf_url || emitBody.pdfUrl || null,
          xml_url: emitBody.xml_url || emitBody.xmlUrl || null,
          emitida_em: emitBody.emitida_em || new Date().toISOString(),
          erro_mensagem: null
        })
      });
      results.push({ id: invoice.id, result: 'autorizada', numero });
    } else {
      const msg = emitBody.message || emitBody.error || emitBody.msg || ('Erro HTTP ' + emitRes.status);
      await fetch(supabaseUrl + '/rest/v1/invoices?id=eq.' + invoice.id, {
        method: 'PATCH',
        headers: Object.assign({}, sbH, { 'Prefer': 'return=minimal' }),
        body: JSON.stringify({ status: 'rejeitada', erro_mensagem: typeof msg === 'string' ? msg : JSON.stringify(msg) })
      });
      results.push({ id: invoice.id, result: 'rejeitada', reason: msg });
    }
  } catch (e) {
    results.push({ id: invoice.id, result: 'skip', reason: 'emit_error: ' + e.message });
  }
}

return [{ json: { checked: invoices.length, results } }];

const input = $input.item.json;
const body = input.body || input;
const supabaseUrl  = input._supabase_url;
const serviceKey   = input._service_key;
const googleToken  = input._google_token;

const invoiceId    = body.invoice_id;
const orgId        = body.organization_id;
const notaasId     = body.notaas_id;
const numero       = body.numero;
const clientId     = body.client_id;
const competencia  = body.competencia;
const valor        = body.valor_servico;

if (!invoiceId || !orgId) throw new Error('invoice_id e organization_id sao obrigatorios');
if (!supabaseUrl || !serviceKey) throw new Error('Variaveis SUPABASE_URL e SUPABASE_SERVICE_KEY nao configuradas');
if (!googleToken) throw new Error('Variavel GOOGLE_ACCESS_TOKEN nao configurada');

const sbH = {
  'apikey': serviceKey,
  'Authorization': 'Bearer ' + serviceKey,
  'Content-Type': 'application/json'
};

// 1. Busca o invoice para obter pdf_url e config da Notaas
const invRes = await fetch(
  supabaseUrl + '/rest/v1/invoices?id=eq.' + invoiceId + '&select=id,status,notaas_id,pdf_url,numero,client_id,organization_id,competencia,valor_servico',
  { headers: sbH }
);
if (!invRes.ok) throw new Error('Erro ao buscar invoice: ' + invRes.status);
const invArr = await invRes.json();
const invoice = Array.isArray(invArr) ? invArr[0] : invArr;
if (!invoice || !invoice.id) throw new Error('Invoice nao encontrado: ' + invoiceId);
if (invoice.status !== 'autorizada') throw new Error('Invoice nao esta autorizada (status: ' + invoice.status + ')');

// 2. Busca config Notaas para obter api_key e base_url
const configRes = await fetch(
  supabaseUrl + '/rest/v1/organization_integrations?organization_id=eq.' + (invoice.organization_id || orgId) + '&integration_type=eq.notaas&select=config',
  { headers: sbH }
);
if (!configRes.ok) throw new Error('Erro ao buscar config Notaas: ' + configRes.status);
const configArr = await configRes.json();
const config = Array.isArray(configArr) ? (configArr[0] && configArr[0].config ? configArr[0].config : {}) : {};
if (!config.api_key) throw new Error('API Key da Notaas nao configurada');

const baseUrl = config.sandbox_mode === true
  ? 'https://sandbox.notaas.com.br'
  : 'https://platform.notaas.com.br';

// 3. Determina a URL do PDF
// Prioridade: pdf_url salvo no invoice > buscar na Notaas pelo notaas_id
let pdfUrl = invoice.pdf_url || null;
const effectiveNotaasId = invoice.notaas_id || notaasId;

if (!pdfUrl && effectiveNotaasId) {
  try {
    const notaRes = await fetch(baseUrl + '/api/v1/notas/' + effectiveNotaasId, {
      headers: { 'x-api-key': config.api_key, 'Content-Type': 'application/json' },
      signal: AbortSignal.timeout(15000)
    });
    if (notaRes.ok) {
      const nota = await notaRes.json();
      pdfUrl = nota.pdf_url || nota.pdfUrl || nota.link_pdf || null;
      if (pdfUrl) {
        await fetch(supabaseUrl + '/rest/v1/invoices?id=eq.' + invoiceId, {
          method: 'PATCH',
          headers: Object.assign({}, sbH, { 'Prefer': 'return=minimal' }),
          body: JSON.stringify({ pdf_url: pdfUrl })
        });
      }
    }
  } catch (e) { /* continua sem pdf_url */ }
}

if (!pdfUrl) throw new Error('URL do PDF nao disponivel para esta nota. Tente novamente mais tarde.');

// 4. Busca folder_id do cliente
const effectiveClientId = invoice.client_id || clientId;
const clientRes = await fetch(
  supabaseUrl + '/rest/v1/clients?id=eq.' + effectiveClientId + '&select=folder_id,name,company',
  { headers: sbH }
);
if (!clientRes.ok) throw new Error('Erro ao buscar cliente: ' + clientRes.status);
const clientArr = await clientRes.json();
const client = Array.isArray(clientArr) ? clientArr[0] : clientArr;
if (!client) throw new Error('Cliente nao encontrado: ' + effectiveClientId);

const folderId = client.folder_id;
if (!folderId) throw new Error('Cliente nao possui pasta no Google Drive configurada. Configure o folder_id do cliente.');

// 5. Baixa o PDF da Notaas
const pdfRes = await fetch(pdfUrl, {
  headers: { 'x-api-key': config.api_key },
  signal: AbortSignal.timeout(60000)
});
if (!pdfRes.ok) throw new Error('Erro ao baixar PDF da Notaas: ' + pdfRes.status);
const pdfBuffer = await pdfRes.arrayBuffer();
const pdfBase64 = Buffer.from(pdfBuffer).toString('base64');

// 6. Monta nome do arquivo
const effectiveNumero = invoice.numero || numero || effectiveNotaasId || invoiceId;
const effectiveCompetencia = (invoice.competencia || competencia || '').replace('-', '_');
const clientName = (client.company || client.name || 'cliente').replace(/[^a-zA-Z0-9 ]/g, '').trim().slice(0, 40);
const fileName = 'NFS-e_' + effectiveNumero + '_' + effectiveCompetencia + '_' + clientName + '.pdf';

// 7. Upload para o Google Drive via multipart
const boundary = 'nfse_pdf_boundary_271828';
const metadata = JSON.stringify({
  name: fileName,
  parents: [folderId],
  mimeType: 'application/pdf',
  description: 'NFS-e ' + effectiveNumero + ' — ' + clientName
});
const multipartBody = '--' + boundary + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' +
  metadata + '\r\n--' + boundary + '\r\nContent-Type: application/pdf\r\nContent-Transfer-Encoding: base64\r\n\r\n' +
  pdfBase64 + '\r\n--' + boundary + '--';

const driveRes = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart', {
  method: 'POST',
  headers: {
    'Authorization': 'Bearer ' + googleToken,
    'Content-Type': 'multipart/related; boundary=' + boundary
  },
  body: multipartBody,
  signal: AbortSignal.timeout(120000)
});

if (!driveRes.ok) {
  const driveErr = await driveRes.json().catch(function() { return {}; });
  throw new Error('Erro ao fazer upload no Google Drive: ' + (driveErr.error && driveErr.error.message ? driveErr.error.message : driveRes.status));
}

const driveData = await driveRes.json();
const driveFileId = driveData.id;
const driveFileUrl = 'https://drive.google.com/file/d/' + driveFileId + '/view';

// 8. Atualiza o invoice com o link do Drive
await fetch(supabaseUrl + '/rest/v1/invoices?id=eq.' + invoiceId, {
  method: 'PATCH',
  headers: Object.assign({}, sbH, { 'Prefer': 'return=minimal' }),
  body: JSON.stringify({
    pdf_url: pdfUrl,
